two-pointer-sorted-sum.referenceSolution:
function twoSumSorted(numbers: number[], target: number): [number, number] | [] {
  let l = 0,
    r = numbers.length - 1;
  while (l < r) {
    const s = numbers[l] + numbers[r];
    if (s === target) return [l + 1, r + 1];
    if (s < target) l++;
    else r--;
  }
  return [];
}

