valid-parentheses-stack.referenceSolution:
function isValidParentheses(s: string): boolean {
  const stack: string[] = [];
  const pairs: Record<string, string> = { ')': '(', '}': '{', ']': '[' };
  for (const char of s) {
    if (char === '(' || char === '{' || char === '[') stack.push(char);
    else if (stack.pop() !== pairs[char]) return false;
  }
  return stack.length === 0;
}

valid-parentheses-stack.referenceSolutionTs:
function isValidParentheses(s: string): boolean {
  const stack: string[] = [];
  const pairs: Record<string, string> = { ')': '(', '}': '{', ']': '[' };
  for (const char of s) {
    if (char === '(' || char === '{' || char === '[') stack.push(char);
    else if (stack.pop() !== pairs[char]) return false;
  }
  return stack.length === 0;
}

binary-search-exact.promptSeed:
Implement classical exact binary search on sorted sequences:

### `binarySearch(nums, target)`
Binary search finds a target value in a **sorted** array by repeatedly checking the middle element and eliminating the half of the search range where the target cannot live.

```array-trace
